package com.parksmart.seed;
import java.math.BigDecimal; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder; import com.parksmart.entity.*; import com.parksmart.repository.*; import com.parksmart.service.ClockService; import java.util.*;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(GarageRepository garages,SpotRepository spots,UserRepository users,PasswordEncoder encoder,ClockService clock){return args->{if(garages.count()>0)return;Garage garage=new Garage("City Centre Garage","1 Market Street",new BigDecimal("50"),new BigDecimal("30"),new BigDecimal("300"));garage.setCreatedAt(clock.now());Garage g=garages.save(garage);List<Spot> values=new ArrayList<>();for(int level=1;level<=3;level++){values.add(new Spot(g,level,"C"+level+"01",SpotType.COMPACT));values.add(new Spot(g,level,"S"+level+"01",SpotType.STANDARD));values.add(new Spot(g,level,"E"+level+"01",SpotType.EV));values.add(new Spot(g,level,"S"+level+"02",SpotType.STANDARD));}spots.saveAll(values);User user=new User("Administrator","admin@parksmart.com",encoder.encode("admin123"));user.setCreatedAt(clock.now());users.save(user);};}}